    if (Array.isArray(bsr)) bsr.forEach(r => { if (r.ticker && r.verdict) F.setup[r.ticker] = r.verdict; });
    else if (bsr && typeof bsr === "object") Object.entries(bsr).forEach(([v, arr]) => (Array.isArray(arr) ? arr : []).forEach(r => { const t = (r && r.ticker) || (typeof r === "string" ? r : null); if (t) F.setup[t] = v; }));
