    const clusterT = new Set([...(((ins || {}).clusters) || []), ...(((ins || {}).decline_clusters) || [])].map(c => c.ticker).filter(Boolean));
    buys.forEach(b => { if (b.ticker && b.date && clusterT.has(b.ticker)) (F.insDates[b.ticker] = F.insDates[b.ticker] || []).push(b.date); });
